<script setup>import{reactive,watch}from'vue';const props=defineProps({roles:Array,initial:Object,busy:Boolean});const emit=defineEmits(['submit','cancel']);const form=reactive({name:'',email:'',status:'active',role_ids:[],password:'',password_confirmation:''});watch(()=>props.initial,v=>{if(v)Object.assign(form,{name:v.name,email:v.email,status:v.status,role_ids:v.platform_roles?.map(r=>r.id)||[],password:'',password_confirmation:''})},{immediate:true});function send(){emit('submit',{...form,role_ids:[...form.role_ids]})}</script><template><form class="space-y-6" @submit.prevent="send"><section class="admin-card"><h2 class="form-section-title">Administrator details</h2><div class="form-grid"><label class="field">Name *<input v-model="form.name" required></label><label class="field">Email *<input v-model="form.email" type="email" required></label><label class="field">Status<select v-model="form.status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><fieldset class="field"><legend>Platform roles *</legend><label v-for="role in roles" :key="role.id" class="feature-option"><input v-model="form.role_ids" type="checkbox" :value="role.id">{{role.name}}</label></fieldset><label class="field">{{initial?'New password (optional)':'Password *'}}<input v-model="form.password" type="password" :required="!initial" autocomplete="new-password"><span class="hint">At least 12 characters with mixed case and a number.</span></label><label class="field">Confirm password<input v-model="form.password_confirmation" type="password" :required="Boolean(form.password)" autocomplete="new-password"></label></div></section><div class="sticky-actions"><button type="button" class="btn-secondary" @click="$emit('cancel')">Cancel</button><button class="btn" :disabled="busy">{{busy?'Saving...':initial?'Save Administrator':'Create Administrator'}}</button></div></form></template>
